{
  "sections": [
    {
      "titre": "Cas d'usage et applications métiers de l'IA générative",
      "chunk_ids": [0, 1, 3],
      "brief": "Couvre l'identification et la priorisation de cas d'usage concrets pour l'IA générative et les outils d'orchestration (ex : génération de rapports, synthèse de données, automatisation de pipelines, agents de planification, orchestration de simulations). Inclut les discussions sur l'adaptabilité des outils à différents templates ou contextes métiers et les propositions de POC minimaux. NE PAS inclure les détails techniques sur les modèles VLM ou le traitement de documents scannés (couvert ailleurs), ni les décisions ou ateliers de priorisation non aboutis (traité dans une autre section)."
    },
    {
      "titre": "Traitement et extraction d'informations à partir de documents",
      "chunk_ids": [2],
      "brief": "Couvre les projets liés à l'extraction d'informations depuis des documents scannés ou manuscrits (ex : documents administratifs), incluant la classification, l'extraction de données structurées (salaire, métier), la détection de conformité, et l'utilisation de modèles VLM. Aborde également les défis techniques comme le prétraitement, le fine-tuning, le contrôle d'anomalies et le déploiement avec monitoring. NE PAS inclure les cas d'usage généraux d'IA générative ou d'orchestration (couvert ailleurs), ni les discussions sur les outils MCP ou N8N hors de ce contexte."
    },
    {
      "titre": "Souveraineté, sécurité et intégration des outils",
      "chunk_ids": [0, 1],
      "brief": "Couvre les enjeux de souveraineté des outils utilisés au sein de RTE, notamment le cloisonnement des données pour éviter leur diffusion externe. Inclut les discussions sur l'intégration de solutions souveraines (ex : MCP, N8N) et leur adaptation aux besoins métiers, ainsi que les contraintes liées à la protection des données. NE PAS inclure les détails techniques des modèles ou des pipelines (couvert ailleurs), ni les cas d'usage spécifiques comme la génération de rapports ou le traitement de documents."
    },
    {
      "titre": "Méthodologie et priorisation des projets",
      "chunk_ids": [4],
      "brief": "Couvre les échanges sur les besoins en ateliers ou méthodologies pour prioriser les cas d'usage (ex : proposition d'atelier design) et les discussions sur les outils MCP/NLP sans décisions concrètes. Inclut les réflexions sur les prochaines étapes pour affiner les besoins. NE PAS inclure les cas d'usage identifiés ou les projets techniques (couvert ailleurs), ni les détails sur les outils d'orchestration ou les modèles."
    }
  ]
}
